<template><view class="p"><jk-page-nav title="资金流水"/><view v-for="x in list" :key="x.id" class="card"><b>{{x.fundFlowTypeText || x.flowTypeText || flowTypeText(x.flowType)}} {{x.changeAmount}}</b><text>{{x.sourceTypeText || sourceTypeText(x.sourceType)}}</text><text>{{x.remark}}</text><text>{{x.createTime}}</text></view></view></template><script>import JkPageNav from '@/components/jk/jk-page-nav.vue';import{getJkFundFlows}from'@/api/jk.js';import{jkFundFlowTypeText,jkSourceTypeText}from'@/utils/jk-display.js';export default{components:{JkPageNav},data(){return{list:[]}},onShow(){getJkFundFlows().then(r=>this.list=r.data||r||[])},methods:{flowTypeText(flowType){return jkFundFlowTypeText(flowType)},sourceTypeText(sourceType){return jkSourceTypeText(sourceType)}}}</script><style scoped>.p{min-height:100vh;background:#f3fbf8;padding:24rpx}.card{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:16rpx;display:flex;flex-direction:column;gap:8rpx}.card text{font-size:24rpx;color:#78918b}</style>
